    {

		if (addToToolbar) {
			setToolBarData(new ToolBarData(DONT_CARE_ICON, MENU_GROUP));
		}
		MenuData menuData = new MenuData(new string[] { "Don't Care" }, DONT_CARE_ICON, MENU_GROUP);
		setPopupMenuData(menuData);
		setEnabled(false);
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Tag_Markup_Item_Dont_Care"));
	}

	/* @Override */
	VTMarkupItemConsideredStatus getTagType() {
		return VTMarkupItemConsideredStatus.IGNORE_DONT_CARE;
	}
}
